insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-pe-148","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The f-block is printed below the main table because inserting the fourteen lanthanoids into period 6 would","options":["violate the modern periodic law","make that row awkwardly wide","change their atomic numbers","turn them into s-block metals"],"answer_index":1,"explanation":"The two-row footnote is a display convention; chemically the lanthanoids still belong in period 6.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"periods-groups-blocks"},{"id":"che-pe-149","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"On moving from left to right across a period, the atomic radius of the elements generally","options":["increases","decreases","remains exactly constant","becomes infinite"],"answer_index":1,"explanation":"Rising effective nuclear charge pulls the same-shell electrons inward, so the atom shrinks.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius"},{"id":"che-pe-150","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"On descending a group, the atomic radius of the elements generally","options":["decreases","increases","becomes zero","is independent of the new shell"],"answer_index":1,"explanation":"Each step down adds a principal shell, which outweighs the extra nuclear charge.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius"},{"id":"che-pe-151","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A cation is always smaller than the parent atom from which it is formed because","options":["a new shell is added","electrons are lost and the remaining cloud is held more tightly","nuclear charge decreases","the ion gains extra shielding"],"answer_index":1,"explanation":"Fewer electrons and a higher Zeff/electron ratio contract the ion relative to the atom.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius"},{"id":"che-pe-152","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"An anion is always larger than the parent atom from which it is formed because","options":["nuclear charge increases","extra electrons raise inter-electronic repulsion and the cloud expands","a shell is completely removed","the ion has fewer electrons than the atom"],"answer_index":1,"explanation":"The added electron(s) swell the electron cloud, so r(anion) > r(atom).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius"},{"id":"che-pe-153","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The covalent radius of an atom is half the internuclear distance in a","options":["heteronuclear ionic crystal","homonuclear single-bonded molecule","van der Waals contact between two non-bonded atoms","metallic unit cell only"],"answer_index":1,"explanation":"In Cl₂, for example, r(cov) = ½ d(Cl–Cl).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius"},{"id":"che-pe-154","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"For the same element the van der Waals radius compared with the covalent radius is","options":["smaller","larger","exactly equal","undefined"],"answer_index":1,"explanation":"van der Waals contact is a non-bonded approach, so the apparent radius is greater than the bonded covalent radius.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius"},{"id":"che-pe-155","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The steady rise of effective nuclear charge across a period pulls the electron cloud inward and therefore","options":["expands the atom","shrinks the atom","adds a new shell","creates an anion"],"answer_index":1,"explanation":"Zeff increases left to right while n stays the same, so atomic size falls.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius"},{"id":"che-pe-156","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Addition of a new principal shell is the main reason atomic size","options":["falls across a period","grows down a group","is identical for all metals","vanishes for noble gases"],"answer_index":1,"explanation":"The extra shell lies farther from the nucleus, so group radii increase top to bottom.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius"},{"id":"che-pe-157","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Metallic radius is half the distance between neighbouring nuclei in a","options":["gaseous homonuclear molecule","metallic crystal","van der Waals dimer","hydrated ion"],"answer_index":1,"explanation":"It is the radius used for metals in the close-packed or body-centred lattice.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius"},{"id":"che-pe-158","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Isoelectronic species are atoms or ions that contain","options":["the same number of protons","the same number of electrons","the same mass number","identical nuclear charges"],"answer_index":1,"explanation":"N³⁻, O²⁻, F⁻, Ne, Na⁺ and Mg²⁺ are a familiar isoelectronic set (10 electrons).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius"},{"id":"che-pe-159","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In an isoelectronic series the ionic radius falls as the","options":["nuclear charge falls","nuclear charge rises","mass number falls","neutron count rises"],"answer_index":1,"explanation":"More protons pull the same number of electrons more tightly, so size decreases with Z.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius"},{"id":"che-pe-160","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The fluoride ion is larger than a neutral fluorine atom because of","options":["loss of the 2p electron","extra electron–electron repulsion in F⁻","a decrease in nuclear charge","lanthanoid contraction"],"answer_index":1,"explanation":"Adding one electron to F expands the 2p cloud, so r(F⁻) > r(F).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius"},{"id":"che-pe-161","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Sodium ion is smaller than a sodium atom because","options":["a 3p electron is added","the entire 3s electron has been removed","nuclear charge of Na⁺ is smaller","Na⁺ has one extra shell"],"answer_index":1,"explanation":"Na is [Ne] 3s¹; Na⁺ is a compact neon-like core with higher Zeff per electron.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius"},{"id":"che-pe-162","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among Li, Na, K and Rb, the atom with the largest covalent radius is","options":["lithium","sodium","potassium","rubidium"],"answer_index":3,"explanation":"Size increases down group 1 as extra shells are added; Rb is the heaviest of the four.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"atomic-ionic-radius"},{"id":"che-pe-163","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among Na, Mg, Al and Si, the smallest atomic radius belongs to","options":["sodium","magnesium","aluminium","silicon"],"answer_index":3,"explanation":"Across period 3, Zeff rises and size falls, so Si is the smallest of this set.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"atomic-ionic-radius"},{"id":"che-pe-164","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The correct order of ionic radii is","options":["Mg²⁺ > Na⁺ > F⁻ > O²⁻","O²⁻ > F⁻ > Na⁺ > Mg²⁺","Na⁺ > O²⁻ > F⁻ > Mg²⁺","F⁻ > O²⁻ > Mg²⁺ > Na⁺"],"answer_index":1,"explanation":"These four ions are isoelectronic (10 e⁻); radius falls as Z rises from 8 (O) to 12 (Mg).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"atomic-ionic-radius"},{"id":"che-pe-165","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Gallium has an atomic radius close to that of aluminium because of","options":["a sudden drop in nuclear charge","the intervening 3d contraction","lanthanoid contraction in period 4","the absence of a 4p subshell"],"answer_index":1,"explanation":"Poorly shielding 3d¹⁰ electrons raise Zeff on Ga and cancel the expected size increase down the group.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"atomic-ionic-radius"},{"id":"che-pe-166","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among the isoelectronic set S²⁻, Cl⁻, K⁺ and Ca²⁺, the smallest species is","options":["S²⁻","Cl⁻","K⁺","Ca²⁺"],"answer_index":3,"explanation":"All have 18 electrons; Ca²⁺ has the largest nuclear charge (Z = 20) and therefore the most contracted cloud.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"atomic-ionic-radius"},{"id":"che-pe-167","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The covalent radius of silicon is larger than that of carbon because silicon","options":["has fewer electrons","has one extra principal shell","has a greater Zeff in the same shell","is a halogen"],"answer_index":1,"explanation":"C is period 2 and Si is period 3; the added n = 3 shell makes Si larger.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"atomic-ionic-radius"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-pe-148","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-149","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-150","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-151","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-152","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-153","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-154","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-155","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-156","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-157","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-158","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-159","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-160","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-161","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-162","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-163","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-164","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-165","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-166","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-pe-167","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do update set appear_count = excluded.appear_count, years = excluded.years, exams = excluded.exams, verified = excluded.verified;
